CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE SCHEMA extensions;
CREATE EXTENSION pgcrypto WITH SCHEMA extensions;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE public.permission_test_grants(user_id uuid NOT NULL, permission_key text NOT NULL, PRIMARY KEY(user_id,permission_key));
CREATE FUNCTION public.has_permission(p_user uuid,p_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.permission_test_grants WHERE user_id=p_user AND permission_key=p_key) $$;
CREATE TABLE public.sales_opportunities(id uuid PRIMARY KEY,opportunity_number text NOT NULL UNIQUE,customer_id uuid NOT NULL,name text NOT NULL,stage text NOT NULL,status text NOT NULL);
CREATE TABLE public.customer_requirements(id uuid PRIMARY KEY,requirement_number text NOT NULL UNIQUE,opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id),customer_id uuid NOT NULL,title text NOT NULL,status text NOT NULL,current_revision integer NOT NULL);
CREATE TABLE public.customer_requirement_revisions(id uuid PRIMARY KEY,requirement_id uuid NOT NULL REFERENCES public.customer_requirements(id),revision_number integer NOT NULL,status text NOT NULL);
CREATE TABLE public.requirement_feasibility_reviews(requirement_id uuid NOT NULL);
CREATE TABLE public.sales_commercial_records(requirement_id uuid NOT NULL);
CREATE TABLE public.requirement_baselines(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),requirement_id uuid NOT NULL);
CREATE TABLE public.requirement_change_requests(requirement_id uuid NOT NULL);
CREATE TABLE public.project_design_inputs(source_requirement_id uuid,source_revision_id uuid);
CREATE TABLE public.customer_portal_shares(entity_id uuid NOT NULL);
CREATE TABLE public.activity_log(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),entity_id uuid,module_key text NOT NULL DEFAULT 'sales',entity_type text NOT NULL DEFAULT 'test',action text NOT NULL DEFAULT 'created',summary text,actor_user_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.data_provenance(entity_id uuid NOT NULL);
CREATE TABLE public.entity_registry(entity_id uuid NOT NULL);
CREATE TABLE public.external_access_events(entity_id uuid NOT NULL);
CREATE TABLE public.sales_project_handovers(baseline_id uuid NOT NULL);
CREATE TABLE public.master_specifications(opportunity_id uuid NOT NULL);
CREATE TABLE public.sales_nda_records(opportunity_id uuid NOT NULL);
CREATE TABLE public.drive_nodes(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid());
CREATE TABLE public.drive_node_revisions(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),node_id uuid NOT NULL REFERENCES public.drive_nodes(id));
CREATE TABLE public.document_control_registers(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),drive_node_id uuid NOT NULL REFERENCES public.drive_nodes(id));
CREATE TABLE public.sales_opportunity_document_locations(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT,drive_root_node_id uuid NOT NULL REFERENCES public.drive_nodes(id),target_folder_node_id uuid NOT NULL REFERENCES public.drive_nodes(id));
CREATE TABLE public.sales_opportunity_structured_drafts(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT);
CREATE TABLE public.sales_opportunity_structured_draft_revisions(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),draft_id uuid NOT NULL REFERENCES public.sales_opportunity_structured_drafts(id));
CREATE TABLE public.sales_opportunity_structured_draft_requests(request_key uuid PRIMARY KEY,opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT);
CREATE TABLE public.sales_opportunity_structured_draft_storage_attempts(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),request_key uuid NOT NULL REFERENCES public.sales_opportunity_structured_draft_requests(request_key));
CREATE TABLE public.sales_opportunity_structured_draft_private_locations(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),drive_folder_node_id uuid NOT NULL REFERENCES public.drive_nodes(id));
CREATE TABLE public.sales_opportunity_structured_draft_revision_locations(revision_id uuid PRIMARY KEY REFERENCES public.sales_opportunity_structured_draft_revisions(id),private_location_id uuid NOT NULL REFERENCES public.sales_opportunity_structured_draft_private_locations(id));
CREATE TABLE public.sales_opportunity_structured_draft_audit_events(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),draft_id uuid NOT NULL REFERENCES public.sales_opportunity_structured_drafts(id));
CREATE TABLE public.sales_opportunity_structured_draft_materializations(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT,drive_node_id uuid NOT NULL REFERENCES public.drive_nodes(id),drive_revision_id uuid NOT NULL REFERENCES public.drive_node_revisions(id),document_control_register_id uuid NOT NULL REFERENCES public.document_control_registers(id));
CREATE TABLE public.sales_opportunity_structured_docx_assignments(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT);
CREATE TABLE public.sales_opportunity_structured_docx_requests(request_key uuid PRIMARY KEY,opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT);
CREATE TABLE public.sales_opportunity_structured_docx_storage_attempts(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),request_key uuid NOT NULL REFERENCES public.sales_opportunity_structured_docx_requests(request_key));
CREATE TABLE public.sales_opportunity_structured_docx_trusted_receipts(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),request_key uuid NOT NULL REFERENCES public.sales_opportunity_structured_docx_requests(request_key));
CREATE TABLE public.sales_opportunity_structured_docx_materializations(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id) ON DELETE RESTRICT,drive_node_id uuid NOT NULL REFERENCES public.drive_nodes(id),drive_revision_id uuid NOT NULL REFERENCES public.drive_node_revisions(id),document_control_register_id uuid NOT NULL REFERENCES public.document_control_registers(id));
CREATE TABLE public.sales_opportunity_structured_docx_audit_events(id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(),request_key uuid NOT NULL REFERENCES public.sales_opportunity_structured_docx_requests(request_key));
CREATE TABLE public.projects(opportunity_id uuid);
